#include <vector>

class Solution {
public:
    std::vector<int> sumZero(int n) {
        std::vector<int> res;
        for (int i = 1; i <= n / 2; ++i) {
            res.push_back(i);
            res.push_back(-i);
        }
        if (n % 2 == 1) res.push_back(0);
        return res;
    }
};

class Solution {
    public int[] sumZero(int n) {
        int[] res = new int[n];
        int idx = 0;
        for (int i = 1; i <= n / 2; i++) {
            res[idx++] = i;
            res[idx++] = -i;
        }
        if (n % 2 == 1) res[idx] = 0;
        return res;
    }
}

var sumZero = function(n) {
    const res = [];
    for (let i = 1; i <= Math.floor(n / 2); i++) {
        res.push(i, -i);
    }
    if (n % 2 === 1) res.push(0);
    return res;
};
